import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Compile with hipcc on ROCm
os.environ.setdefault("CXX", "hipcc")

# Fused abs-max reduction + fused quantize(+optional transpose) to FP8
# - amax_abs_hip: computes max(abs(x)) without materializing abs(x)
# - quantize_fp8_hip: y = clamp(x*scale, [-fp8_max, fp8_max]) cast to fp8
# - transpose_quantize_fp8_hip: reads (K,N) and writes fp8 (N,K)

_fp8_ops_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <hip/hip_runtime.h>

#include <c10/util/Float8_e4m3fn.h>
#include <c10/util/Float8_e5m2.h>

static inline __device__ float to_float(float x) { return x; }
static inline __device__ float to_float(at::Half x) { return (float)x; }

template <typename in_t>
__global__ void absmax_atomic_kernel(const in_t* __restrict__ x, int64_t n, float* __restrict__ out) {
    float thread_max = 0.0f;
    int64_t idx = (int64_t)blockIdx.x * blockDim.x * 4 + threadIdx.x;

    #pragma unroll
    for (int i = 0; i < 4; i++) {
        int64_t j = idx + (int64_t)i * blockDim.x;
        if (j < n) {
            float v = to_float(x[j]);
            v = fabsf(v);
            thread_max = fmaxf(thread_max, v);
        }
    }

    __shared__ float smem[256];
    smem[threadIdx.x] = thread_max;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            smem[threadIdx.x] = fmaxf(smem[threadIdx.x], smem[threadIdx.x + stride]);
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        atomicMax((unsigned int*)out, __float_as_uint(smem[0]));
    }
}

template <typename in_t, typename out_t>
__global__ void quantize_fp8_kernel(const in_t* __restrict__ x,
                                   int64_t n,
                                   const float* __restrict__ scale_ptr,
                                   float fp8_max,
                                   out_t* __restrict__ out) {
    __shared__ float s_scale;
    if (threadIdx.x == 0) s_scale = scale_ptr[0];
    __syncthreads();
    float scale = s_scale;

    int64_t base = (int64_t)blockIdx.x * blockDim.x * 4 + threadIdx.x;
    #pragma unroll
    for (int i = 0; i < 4; i++) {
        int64_t idx = base + (int64_t)i * blockDim.x;
        if (idx < n) {
            float v = to_float(x[idx]) * scale;
            v = fminf(fp8_max, fmaxf(-fp8_max, v));
            out[idx] = (out_t)v;
        }
    }
}

template <typename in_t, typename out_t>
__global__ void transpose_quantize_fp8_kernel(const in_t* __restrict__ w,
                                              int K, int N,
                                              const float* __restrict__ scale_ptr,
                                              float fp8_max,
                                              out_t* __restrict__ out) {
    __shared__ float s_scale;
    if (threadIdx.x == 0) s_scale = scale_ptr[0];
    __syncthreads();
    float scale = s_scale;

    int64_t total = (int64_t)K * (int64_t)N;
    int64_t base = (int64_t)blockIdx.x * blockDim.x * 4 + threadIdx.x;

    #pragma unroll
    for (int u = 0; u < 4; u++) {
        int64_t tid = base + (int64_t)u * blockDim.x;
        if (tid < total) {
            int i = (int)(tid % K);
            int j = (int)(tid / K);
            float v = to_float(w[(int64_t)i * N + j]) * scale;
            v = fminf(fp8_max, fmaxf(-fp8_max, v));
            out[tid] = (out_t)v;
        }
    }
}

torch::Tensor amax_abs_hip(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "amax_abs_hip: x must be CUDA/HIP tensor");
    TORCH_CHECK(x.is_contiguous(), "amax_abs_hip: x must be contiguous");
    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kFloat,
                "amax_abs_hip: only float16/float32 supported");

    auto out = torch::zeros({1}, torch::TensorOptions().device(x.device()).dtype(at::kFloat));

    int64_t n = x.numel();
    const int threads = 256;
    const int64_t elems_per_block = (int64_t)threads * 4;
    int blocks = (int)((n + elems_per_block - 1) / elems_per_block);

    cudaStream_t stream = at::cuda::getDefaultCUDAStream().stream();

    if (x.scalar_type() == at::kHalf) {
        absmax_atomic_kernel<at::Half><<<blocks, threads, 0, stream>>>(
            (const at::Half*)x.data_ptr<at::Half>(), n, (float*)out.data_ptr<float>());
    } else {
        absmax_atomic_kernel<float><<<blocks, threads, 0, stream>>>(
            (const float*)x.data_ptr<float>(), n, (float*)out.data_ptr<float>());
    }
    return out;
}

torch::Tensor quantize_fp8_hip(torch::Tensor x, torch::Tensor scale, double fp8_max, bool use_e4m3) {
    TORCH_CHECK(x.is_cuda(), "quantize_fp8_hip: x must be CUDA/HIP tensor");
    TORCH_CHECK(scale.is_cuda(), "quantize_fp8_hip: scale must be CUDA/HIP tensor");
    TORCH_CHECK(x.is_contiguous(), "quantize_fp8_hip: x must be contiguous");
    TORCH_CHECK(scale.numel() == 1, "quantize_fp8_hip: scale must be scalar tensor");
    TORCH_CHECK(scale.scalar_type() == at::kFloat, "quantize_fp8_hip: scale must be float32");
    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kFloat,
                "quantize_fp8_hip: only float16/float32 supported");

    at::ScalarType out_st = use_e4m3 ? at::ScalarType::Float8E4M3FN : at::ScalarType::Float8E5M2;
    auto out = torch::empty(x.sizes(), x.options().dtype(out_st));

    int64_t n = x.numel();
    const int threads = 256;
    const int64_t elems_per_block = (int64_t)threads * 4;
    int blocks = (int)((n + elems_per_block - 1) / elems_per_block);
    cudaStream_t stream = at::cuda::getDefaultCUDAStream().stream();

    const float* scale_ptr = (const float*)scale.data_ptr<float>();
    float maxv = (float)fp8_max;

    if (use_e4m3) {
        if (x.scalar_type() == at::kHalf) {
            quantize_fp8_kernel<at::Half, c10::Float8_e4m3fn><<<blocks, threads, 0, stream>>>(
                (const at::Half*)x.data_ptr<at::Half>(), n, scale_ptr, maxv,
                (c10::Float8_e4m3fn*)out.data_ptr<c10::Float8_e4m3fn>());
        } else {
            quantize_fp8_kernel<float, c10::Float8_e4m3fn><<<blocks, threads, 0, stream>>>(
                (const float*)x.data_ptr<float>(), n, scale_ptr, maxv,
                (c10::Float8_e4m3fn*)out.data_ptr<c10::Float8_e4m3fn>());
        }
    } else {
        if (x.scalar_type() == at::kHalf) {
            quantize_fp8_kernel<at::Half, c10::Float8_e5m2><<<blocks, threads, 0, stream>>>(
                (const at::Half*)x.data_ptr<at::Half>(), n, scale_ptr, maxv,
                (c10::Float8_e5m2*)out.data_ptr<c10::Float8_e5m2>());
        } else {
            quantize_fp8_kernel<float, c10::Float8_e5m2><<<blocks, threads, 0, stream>>>(
                (const float*)x.data_ptr<float>(), n, scale_ptr, maxv,
                (c10::Float8_e5m2*)out.data_ptr<c10::Float8_e5m2>());
        }
    }

    return out;
}

torch::Tensor transpose_quantize_fp8_hip(torch::Tensor w, torch::Tensor scale, double fp8_max, bool use_e4m3) {
    TORCH_CHECK(w.is_cuda(), "transpose_quantize_fp8_hip: w must be CUDA/HIP tensor");
    TORCH_CHECK(scale.is_cuda(), "transpose_quantize_fp8_hip: scale must be CUDA/HIP tensor");
    TORCH_CHECK(w.is_contiguous(), "transpose_quantize_fp8_hip: w must be contiguous");
    TORCH_CHECK(w.dim() == 2, "transpose_quantize_fp8_hip: w must be 2D");
    TORCH_CHECK(scale.numel() == 1, "transpose_quantize_fp8_hip: scale must be scalar tensor");
    TORCH_CHECK(scale.scalar_type() == at::kFloat, "transpose_quantize_fp8_hip: scale must be float32");
    TORCH_CHECK(w.scalar_type() == at::kHalf || w.scalar_type() == at::kFloat,
                "transpose_quantize_fp8_hip: only float16/float32 supported");

    int K = (int)w.size(0);
    int N = (int)w.size(1);

    at::ScalarType out_st = use_e4m3 ? at::ScalarType::Float8E4M3FN : at::ScalarType::Float8E5M2;
    auto out = torch::empty({N, K}, w.options().dtype(out_st));

    int64_t total = (int64_t)K * (int64_t)N;
    const int threads = 256;
    const int64_t elems_per_block = (int64_t)threads * 4;
    int blocks = (int)((total + elems_per_block - 1) / elems_per_block);
    cudaStream_t stream = at::cuda::getDefaultCUDAStream().stream();

    const float* scale_ptr = (const float*)scale.data_ptr<float>();
    float maxv = (float)fp8_max;

    if (use_e4m3) {
        if (w.scalar_type() == at::kHalf) {
            transpose_quantize_fp8_kernel<at::Half, c10::Float8_e4m3fn><<<blocks, threads, 0, stream>>>(
                (const at::Half*)w.data_ptr<at::Half>(), K, N, scale_ptr, maxv,
                (c10::Float8_e4m3fn*)out.data_ptr<c10::Float8_e4m3fn>());
        } else {
            transpose_quantize_fp8_kernel<float, c10::Float8_e4m3fn><<<blocks, threads, 0, stream>>>(
                (const float*)w.data_ptr<float>(), K, N, scale_ptr, maxv,
                (c10::Float8_e4m3fn*)out.data_ptr<c10::Float8_e4m3fn>());
        }
    } else {
        if (w.scalar_type() == at::kHalf) {
            transpose_quantize_fp8_kernel<at::Half, c10::Float8_e5m2><<<blocks, threads, 0, stream>>>(
                (const at::Half*)w.data_ptr<at::Half>(), K, N, scale_ptr, maxv,
                (c10::Float8_e5m2*)out.data_ptr<c10::Float8_e5m2>());
        } else {
            transpose_quantize_fp8_kernel<float, c10::Float8_e5m2><<<blocks, threads, 0, stream>>>(
                (const float*)w.data_ptr<float>(), K, N, scale_ptr, maxv,
                (c10::Float8_e5m2*)out.data_ptr<c10::Float8_e5m2>());
        }
    }

    return out;
}
"""

_fp8_ops = load_inline(
    name="fp8_ops_ext",
    cpp_sources=_fp8_ops_src,
    functions=[
        "amax_abs_hip",
        "quantize_fp8_hip",
        "transpose_quantize_fp8_hip",
    ],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

        self._w_fp8 = None
        self._w_scale_inv = None
        self._w_version = None
        self._w_device = None

        self.fp8_ops = _fp8_ops

    def compute_scale_fp32(self, x: torch.Tensor) -> torch.Tensor:
        # Custom fused absmax reduction (FP32 output) to avoid materializing abs(x)
        amax = self.fp8_ops.amax_abs_hip(x.contiguous())  # float32 [1]
        scale = self.fp8_max / amax.clamp(min=1e-12)
        return scale  # float32 [1]

    def _maybe_refresh_weight_cache(self):
        dev = self.weight.device
        ver = getattr(self.weight, "_version", None)
        if (
            self._w_fp8 is None
            or self._w_device != dev
            or (ver is not None and self._w_version != ver)
        ):
            w_scale = self.compute_scale_fp32(self.weight)
            self._w_scale_inv = (1.0 / w_scale).to(torch.float32)
            # Produce FP8 weights in (N, K) layout directly (fused transpose+quantize)
            self._w_fp8 = self.fp8_ops.transpose_quantize_fp8_hip(
                self.weight.contiguous(),
                w_scale,
                float(self.fp8_max),
                bool(self.use_e4m3),
            )
            self._w_device = dev
            self._w_version = ver

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        input_dtype = x.dtype
        batch_size, seq_len, _ = x.shape

        x_2d = x.view(-1, self.K)

        x_scale = self.compute_scale_fp32(x_2d)
        x_scale_inv = (1.0 / x_scale).to(torch.float32)

        x_fp8 = self.fp8_ops.quantize_fp8_hip(
            x_2d.contiguous(),
            x_scale,
            float(self.fp8_max),
            bool(self.use_e4m3),
        )

        self._maybe_refresh_weight_cache()

        out = torch._scaled_mm(
            x_fp8,
            self._w_fp8.t(),
            scale_a=x_scale_inv,
            scale_b=self._w_scale_inv,
            out_dtype=input_dtype,
        )
        return out.view(batch_size, seq_len, self.N)


