class ModelNew(nn.Module):
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

        # Cache FP8 weights/scales (since weights are constant in inference)
        self._w_fp8 = None
        self._w_scale_inv = None
        self._w_version = None
        self._w_device = None

        self.fp8_ops = _fp8_ops

    def compute_scale_fp32(self, x: torch.Tensor) -> torch.Tensor:
        # Custom fused absmax reduction (FP32 output) to avoid materializing abs(x)
        amax = self.fp8_ops.amax_abs_hip(x.contiguous())  # float32 [1]
        scale = self.fp8_max / amax.clamp(min=1e-12)
        return scale  # float32 [1]

    def _maybe_refresh_weight_cache(self):
        dev = self.weight.device
        ver = getattr(self.weight, "_version", None)
        if (
            self._w_fp8 is None
            or self._w_device != dev
            or (ver is not None and self._w_version != ver)
        ):
            w_scale = self.compute_scale_fp32(self.weight)
            self._w_scale_inv = (1.0 / w_scale).to(torch.float32)
            # Produce FP8 weights in (N, K) layout directly (fused transpose+quantize)
            self._w_fp8 = self.fp8_ops.transpose_quantize_fp8_hip(
                self.weight.contiguous(),
                w_scale,
                float(self.fp8_max),
                bool(self.use_e4m3),
            )
            self._w_device = dev
            self._w_version = ver

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        input_dtype = x.dtype
        batch_size, seq_len, _ = x.shape

        x_2d = x.view(-1, self.K)

        x_scale = self.compute_scale_fp32(x_2d)
        x_scale_inv = (1.0 / x_scale).to(torch.float32)

        # Fused quantize (x*scale + clamp + cast) -> FP8
        x_fp8 = self.fp8_ops.quantize_fp8_hip(
            x_2d.contiguous(),
            x_scale,
            float(self.fp8_max),
            bool(self.use_e4m3),
        )

        self._maybe_refresh_weight_cache()

        out = torch._scaled_mm(
            x_fp8,
            self._w_fp8.t(),
            scale_a=x_scale_inv,
            scale_b=self._w_scale_inv,
            out_dtype=input_dtype,
        )
        return out.view(batch_size, seq_len, self.N)


